/bin/bash -lc "cd /work && python - <<'PY'
import sim, numpy as np
s=sim.Sim(); m=s.model; d=s.data
names=s.actuator_names(); idx={n:i for i,n in enumerate(names)}
LANK=idx['left_ankle']; RANK=idx['right_ankle']
lo,hi=m.actuator_ctrlrange[:,0],m.actuator_ctrlrange[:,1]

def pitch():
    z=d.xmat[s.torso_body_id].reshape(3,3)[:,2]
    return float(np.arctan2(z[0], z[2]))

def omega_y():
    return float(d.cvel[s.torso_body_id][4])

k=30; kd=3
for t in range(500):
    p=pitch(); w=omega_y()
    u=np.zeros(m.nu)
    corr = -k*(-p) - kd*(-w)
    u[LANK]=corr
    u[RANK]=corr
    d.ctrl[:] = np.clip(u,lo,hi)
    s.step(1)
    if t%100==0:
        print('t',d.time,'up',s.torso_up(),'pitch',p,'ankle_u',corr)
PY"

